  const lengthInputs = lengthSection ? Array.from(lengthSection.querySelectorAll('input, label, [class*="item"]')).map(el => ({
    tag: el.tagName,
    type: el.type,
    name: el.name,
    value: el.value,
    text: el.textContent?.trim().replace(/\s+/g, ' ')
  })) : "No length section found";

  // Find departure date options
  const oct2026 = Array.from(document.querySelectorAll('input, label, button, a')).filter(el =>
    /october 2026/i.test(el.textContent || el.value || '')
  ).map(el => ({
    tag: el.tagName,
    id: el.id,
    className: el.className,
    text: el.textContent?.trim(),
    name: el.name,
    value: el.value,
    checked: el.checked
  }));

  // Find deal or discount filters
  const dealFilters = Array.from(document.querySelectorAll('input, label, [class*="filter"]')).filter(el =>
    /deal|discount|sale|special offer/i.test(el.textContent || el.name || el.value || '')
  ).map(el => ({
    tag: el.tagName,
    id: el.id,
    text: el.textContent?.trim().replace(/\s+/g, ' ').slice(0, 50),
    name: el.name,
    value: el.value
  }));

  // Find sort dropdown / select
  const sortSelect = document.querySelector('select[data-cy*="sort"], select[class*="sort"]');
  const sortDetails = sortSelect ? {
    name: sortSelect.name,
    value: sortSelect.value,
    options: Array.from(sortSelect.options).map(o => ({ value: o.value, text: o.text }))
  } : "No sort select found";

  return {
    lengthInputs: lengthInputs.slice(0, 15),
    oct2026,
    dealFilters: dealFilters.slice(0, 15),
    sortDetails
  };
});
