const tabId = 118779795;
const tourCardsDetailed = await browserjs(tabId, () => {
  const cards = Array.from(document.querySelectorAll('.js-serp-tour, [data-cy="serp-tour"], li.tour'));
  return cards.map(c => {
    // Let's get all text inside heading / title links
    const heading = c.querySelector('h2, h3, h4, h5, [class*="heading"], [class*="title"]');
    const links = Array.from(c.querySelectorAll('a[href*="/t/"]')).map(a => ({
      href: a.href,
      text: a.textContent.trim()
    })).filter(x => x.text);

    // Look for duration like "11 days", "12 days", etc.
    const allText = c.textContent;
    const daysMatch = allText.match(/(\d+)\s*days?/i);
    const priceMatch = allText.match(/US\$[\d,]+/g);
    const discountMatch = allText.match(/\d+%\s*Off|Save\s*[\$\d%]+/i);
    const dateMatch = allText.match(/\d{1,2}\s+[A-Za-z]{3},\s+2026/);
    const operator = c.querySelector('[class*="operator"]')?.textContent?.trim();

    return {
      links,
      headingText: heading?.textContent?.trim().replace(/\s+/g, ' '),
      duration: daysMatch ? daysMatch[0] : null,
      prices: priceMatch,
      discount: discountMatch ? discountMatch[0] : null,
      date: dateMatch ? dateMatch[0] : null,
      operator
    };
  });
});
console.log(JSON.stringify(tourCardsDetailed.slice(0, 10), null, 2));

